    int depth,
    unsigned int class,
    Visual * visual,
    unsigned long valuemask,
    XSetWindowAttributes * attributes);
*/

Window window = XCreateWindow(
    display,
    DefaultRootWindow(display),
    WINDOW_LEFT,
    WINDOW_TOP,
    WINDOW_WIDTH,
    WINDOW_HEIGHT,
    /* border_width = */ 0,
    /* depth = */ CopyFromParent,
    /* class = */ InputOutput,
    /* visual = */ CopyFromParent,
