    screen->root,
    WINDOW_LEFT,
    WINDOW_TOP,
    WINDOW_WIDTH,
    WINDOW_HEIGHT,
    /* border_width = */ 0,
    /* class = */ XCB_WINDOW_CLASS_INPUT_OUTPUT,
    /* visual = */ XCB_COPY_FROM_PARENT,
    /* valuemask = */ 0,
    /* attributes = */ NULL);

/*
int XMapWindow(
