/*
Display * XOpenDisplay(
    const char * display_name);

int DefaultScreen(
    Display * display);
*/

Display * display = XOpenDisplay(NULL);
int screen_number = DefaultScreen(display);

/*
xcb_connection_t * xcb_connect(
    const char * display_name,
    int * default_screen);
*/

int screen_number;
xcb_connection_t * connection = xcb_connect(NULL, &screen_number);

/*
const struct xcb_setup_t * xcb_get_setup(
    xcb_connection_t * c);

xcb_screen_iterator_t xcb_setup_roots_iterator(
    const xcb_setup_t * R);

void xcb_screen_next(
    xcb_screen_iterator_t * i);
*/

xcb_screen_iterator_t iter;
xcb_screen_t * screen;
iter = xcb_setup_roots_iterator(xcb_get_setup(connection));
screen = iter.data;
for(; iter.rem; screen_number--, xcb_screen_next(&iter))
{
    if(screen_number == 0)
    {
        screen = iter.data;
        break;
    }
}

/*
unsigned long WhitePixel(
    Display * display,
    int screen_number);

unsigned long BlackPixel(
    Display * display,
    int screen_number);
*/

XSetWindowAttributes window_attributes;
window_attributes.background_pixel = WhitePixel(display, screen_number);
window_attributes.border_pixel = BlackPixel(display, screen_number);

