    unsigned int border_width,
    int depth,
    unsigned int class,
    Visual * visual,
    unsigned long valuemask,
    XSetWindowAttributes * attributes);
*/

Window window = XCreateWindow(
    display,
    RootWindow(display, screen_number),
    WINDOW_LEFT,
    WINDOW_TOP,
    WINDOW_WIDTH,
    WINDOW_HEIGHT,
    /* border_width = */ 0,
    /* depth = */ CopyFromParent,
    /* class = */ InputOutput,
    /* visual = */ CopyFromParent,
    /* valuemask = */ CWBackPixel | CWBorderPixel,
    /* attributes = */ &window_attributes);

/* these attributes must come in this order */
uint32_t window_attributes[2];
/* background_pixel */
window_attributes[0] = screen->white_pixel;
/* border_pixel */
window_attributes[1] = screen->black_pixel;

/*
uint32_t xcb_generate_id(xcb_connection_t * conn);

xcb_void_cookie_t xcb_create_window(
    xcb_connection_t * conn,
    uint8_t depth,
    xcb_window_t wid,
    xcb_window_t parent,
    int16_t x,
    int16_t y,
    uint16_t width,
    uint16_t height,
    uint16_t border_width,
    uint16_t _class,
    xcb_visualid_t visual,
    uint32_t value_mask,
    const void * value_list);
*/

xcb_window_t window = xcb_generate_id(connection);
xcb_create_window(
    connection,
    /* depth = */ XCB_COPY_FROM_PARENT,
    window,
    screen->root,
    WINDOW_LEFT,
    WINDOW_TOP,
    WINDOW_WIDTH,
    WINDOW_HEIGHT,
    /* border_width = */ 0,
