    /* visual = */ XCB_COPY_FROM_PARENT,
    /* valuemask = */ XCB_CW_BACK_PIXEL | XCB_CW_BORDER_PIXEL,
    /* attributes = */ &window_attributes);

/*
int XChangeWindowAttributes(
