XSetWindowAttributes window_attributes;
window_attributes.background_pixel = WhitePixel(display, screen_number);
window_attributes.border_pixel = BlackPixel(display, screen_number);
window_attributes.event_mask =
    ExposureMask /* part of the window needs redrawing */
    | ButtonPressMask /* a mouse button is pressed */
    | ButtonReleaseMask /* a mouse button is released */
    | KeyPressMask /* a keyboard key is pressed */
    | KeyReleaseMask /* a keyboard key is released */
    | PointerMotionMask /* the mouse cursor is moved */
    | EnterWindowMask /* the mouse cursor entered the window */
    | LeaveWindowMask /* the mouse cursor left the window */
    | StructureNotifyMask; /* the window is moved, resized, repositioned in the stack ordering, etc. */

Window window = XCreateWindow(
    display,
    RootWindow(display, screen_number),
    WINDOW_LEFT,
    WINDOW_TOP,
    WINDOW_WIDTH,
    WINDOW_HEIGHT,
    /* border_width = */ 0,
    /* depth = */ CopyFromParent,
    /* class = */ InputOutput,
    /* visual = */ CopyFromParent,
    /* valuemask = */ CWBackPixel | CWBorderPixel | CWEventMask,
    /* attributes = */ &window_attributes);

/* these attributes must come in this order */
uint32_t window_attributes[3];
/* background_pixel */
window_attributes[0] = screen->white_pixel;
/* border_pixel */
window_attributes[1] = screen->black_pixel;
/* event_mask */
window_attributes[2] =
    XCB_EVENT_MASK_EXPOSURE /* part of the window needs redrawing */
    | XCB_EVENT_MASK_BUTTON_PRESS /* a mouse button is pressed */
    | XCB_EVENT_MASK_BUTTON_RELEASE /* a mouse button is released */
    | XCB_EVENT_MASK_KEY_PRESS /* a keyboard key is pressed */
    | XCB_EVENT_MASK_KEY_RELEASE /* a keyboard key is released */
    | XCB_EVENT_MASK_POINTER_MOTION /* the mouse cursor is moved */
    | XCB_EVENT_MASK_ENTER_WINDOW /* the mouse cursor entered the window */
    | XCB_EVENT_MASK_LEAVE_WINDOW /* the mouse cursor left the window */
    | XCB_EVENT_MASK_STRUCTURE_NOTIFY; /* the window is moved, resized, repositioned in the stack ordering, etc. */

xcb_window_t window = xcb_generate_id(connection);
xcb_create_window(
    connection,
    /* depth = */ XCB_COPY_FROM_PARENT,
    window,
    screen->root,
    WINDOW_LEFT,
    WINDOW_TOP,
    WINDOW_WIDTH,
    WINDOW_HEIGHT,
    /* border_width = */ 0,
    /* class = */ XCB_WINDOW_CLASS_INPUT_OUTPUT,
    /* visual = */ XCB_COPY_FROM_PARENT,
