    /* attributes = */ &window_attributes);

XTextProperty window_title;
char * window_title_text = WINDOW_TITLE;
XStringListToTextProperty(&window_title_text, 1, &window_title);

XSetWMName(display, window, &window_title);
XSetWMIconName(display, window, &window_title);

xcb_intern_atom_reply_t * intern_atom_reply = xcb_intern_atom_reply(
    connection,
    xcb_intern_atom(
        connection,
        false,
        sizeof "WM_PROTOCOLS" - 1,
        "WM_PROTOCOLS"),
    NULL);
xcb_atom_t WM_PROTOCOLS;
if(intern_atom_reply)
{
    WM_PROTOCOLS = intern_atom_reply->atom;
    free(intern_atom_reply);
}

intern_atom_reply = xcb_intern_atom_reply(
    connection,
    xcb_intern_atom(
        connection,
        false,
        sizeof "WM_DELETE_WINDOW" - 1,
        "WM_DELETE_WINDOW"),
    NULL);
xcb_atom_t WM_DELETE_WINDOW;
if(intern_atom_reply)
{
    WM_DELETE_WINDOW = intern_atom_reply->atom;
    free(intern_atom_reply);
}

Atom atoms[1];
atoms[0] = WM_DELETE_WINDOW;
XSetWMProtocols(
    display,
