    points[0].y = Y1;
    points[1].x = X2;
    points[1].y = Y2;

    xcb_poly_line(
        connection,
        XCB_COORD_MODE_ORIGIN,
        window,
        gc,
        2,
        points);

    xcb_flush(connection);
}
break;

case KeyPress:
case KeyRelease:
    fprintf(stderr, "Key%s{keycode = 0x%02X, state = 0x%04X}\n",
        event.type == KeyPress ? "Press" : "Release",
        event.xkey.keycode, event.xkey.state
    );
break;

case ButtonPress:
case ButtonRelease:
    fprintf(stderr, "Button%s{button = %d, position = (%d, %d)}\n",
        event.type == ButtonPress ? "Press" : "Release",
        event.xbutton.button,
        event.xbutton.x,
        event.xbutton.y
    );
break;

case XCB_BUTTON_PRESS:
case XCB_BUTTON_RELEASE:
    fprintf(stderr, "Button%s{button = %d, position = (%d, %d)}\n",
        (event->response_type & ~0x80) == XCB_BUTTON_PRESS ? "Press" : "Release",
        ((xcb_button_press_event_t *)event)->detail,
        ((xcb_button_press_event_t *)event)->event_x,
        ((xcb_button_press_event_t *)event)->event_y
    );
break;

case MotionNotify:
    fprintf(stderr, "MotionNotify(%d, %d)\n",
        event.xmotion.x, event.xmotion.y
    );
break;

case XCB_MOTION_NOTIFY:
    fprintf(stderr, "MotionNotify(%d, %d)\n",
        ((xcb_motion_notify_event_t *)event)->event_x,
        ((xcb_motion_notify_event_t *)event)->event_y
    );
break;

case EnterNotify:
    fprintf(stderr, "EnterNotify(%d, %d)\n",
        event.xcrossing.x, event.xcrossing.y
    );
break;
case LeaveNotify:
    fprintf(stderr, "LeaveNotify(%d, %d)\n",
        event.xcrossing.x, event.xcrossing.y
    );
break;

case XCB_ENTER_NOTIFY:
    fprintf(stderr, "EnterNotify(%d, %d)\n",
        ((xcb_enter_notify_event_t *)event)->event_x,
        ((xcb_enter_notify_event_t *)event)->event_y
    );
break;
case XCB_LEAVE_NOTIFY:
    fprintf(stderr, "LeaveNotify(%d, %d)\n",
        ((xcb_leave_notify_event_t *)event)->event_x,
        ((xcb_leave_notify_event_t *)event)->event_y
    );
break;

case ConfigureNotify:
    fprintf(stderr, "ConfigureNotify(%d, %d)-(%d, %d)\n",
        event.xconfigure.x, event.xconfigure.y,
        event.xconfigure.x + event.xconfigure.width,
        event.xconfigure.y + event.xconfigure.height
    );
break;

case XCB_CONFIGURE_NOTIFY:
    fprintf(stderr, "ConfigureNotify(%d, %d)-(%d, %d)\n",
        ((xcb_configure_notify_event_t *)event)->x,
        ((xcb_configure_notify_event_t *)event)->y,
        ((xcb_configure_notify_event_t *)event)->x + ((xcb_configure_notify_event_t *)event)->width,
        ((xcb_configure_notify_event_t *)event)->y + ((xcb_configure_notify_event_t *)event)->height
    );
break;

        } // end switch
        if(!is_running)
