int width = 0, height = 0, state = 0;
bool is_running = true;
bool needs_redraw = false;
clock_t last_tick = clock();
while(is_running)
{
    if(XPending(display))
    {
        XEvent event;
        XNextEvent(display, &event);
        switch(event.type)
        {

int width = 0, height = 0, state = 0;
bool is_running = true;
bool needs_redraw = false;
clock_t last_tick = clock();
while(is_running)
{
    xcb_generic_event_t * event;
    if((event = xcb_poll_for_event(connection)))
    {
        switch(event->response_type & ~0x80)
        {

case Expose:
    fprintf(stderr, "Expose(%d, %d)-(%d, %d)\n",
        event.xexpose.x, event.xexpose.y,
        event.xexpose.x + event.xexpose.width,
        event.xexpose.y + event.xexpose.height
    );

    needs_redraw = true;
break;

case XCB_EXPOSE:
    fprintf(stderr, "Expose(%d, %d)-(%d, %d)\n",
        ((xcb_expose_event_t *)event)->x,
        ((xcb_expose_event_t *)event)->y,
        ((xcb_expose_event_t *)event)->x + ((xcb_expose_event_t *)event)->width,
        ((xcb_expose_event_t *)event)->y + ((xcb_expose_event_t *)event)->height
    );

    needs_redraw = true;
break;

case ConfigureNotify:
    fprintf(stderr, "ConfigureNotify(%d, %d)-(%d, %d)\n",
        event.xconfigure.x, event.xconfigure.y,
        event.xconfigure.x + event.xconfigure.width,
        event.xconfigure.y + event.xconfigure.height
    );
    width = event.xconfigure.width;
    height = event.xconfigure.height;
break;

case XCB_CONFIGURE_NOTIFY:
    fprintf(stderr, "ConfigureNotify(%d, %d)-(%d, %d)\n",
        ((xcb_configure_notify_event_t *)event)->x,
        ((xcb_configure_notify_event_t *)event)->y,
        ((xcb_configure_notify_event_t *)event)->x + ((xcb_configure_notify_event_t *)event)->width,
        ((xcb_configure_notify_event_t *)event)->y + ((xcb_configure_notify_event_t *)event)->height
    );
    width = ((xcb_configure_notify_event_t *)event)->width;
    height = ((xcb_configure_notify_event_t *)event)->height;
break;

        } // end switch
    } // end if

    clock_t next_tick = clock();
    if(next_tick - last_tick >= CLOCKS_PER_SEC / 5)
    {
        last_tick = next_tick;
        needs_redraw = true;
        state++;
    }

    if(needs_redraw)
    {
        fprintf(stderr, "Redraw\n");

        XGCValues gc_attributes;
        gc_attributes.foreground = WhitePixel(display, screen_number);
        GC gc = XCreateGC(
            display,
            window,
            /* valuemask = */ GCForeground,
            /* values = */ &gc_attributes);

        XRectangle rectangles[1];
        rectangles[0].x = 0;
        rectangles[0].y = 0;
        rectangles[0].width = width;
        rectangles[0].height = height;

        XFillRectangles(
            display,
            window,
            gc,
            rectangles,
            1);

        gc_attributes.foreground = BlackPixel(display, screen_number);
        XChangeGC(
            display,
            gc,
            /* valuemask = */ GCForeground,
            /* values = */ &gc_attributes);

        XPoint points[2];

        points[0].x = X1 + (state & 255);
        points[0].y = Y1;
        points[1].x = X2 - (state & 255);
        points[1].y = Y2;

        XDrawLines(
            display,
            window,
            gc,
            points,
            2,
            CoordModeOrigin);

        XFlush(display);

        needs_redraw = false;
    }
} // end while

        } // end switch
        free(event);
    } // end if

    clock_t next_tick = clock();
    if(next_tick - last_tick >= CLOCKS_PER_SEC / 5)
    {
        last_tick = next_tick;
        needs_redraw = true;
        state++;
    }

    if(needs_redraw)
    {
        fprintf(stderr, "Redraw\n");

        xcb_gcontext_t gc = xcb_generate_id(connection);
        uint32_t gc_attributes[1];
        gc_attributes[0] = screen->white_pixel;
        xcb_create_gc(
            connection,
            gc,
            window,
            /* valuemask = */ XCB_GC_FOREGROUND,
            /* values = */ gc_attributes);

        xcb_rectangle_t rectangles[1];
        rectangles[0].x = 0;
        rectangles[0].y = 0;
        rectangles[0].width = width;
        rectangles[0].height = height;

        xcb_poly_fill_rectangle(
            connection,
            window,
            gc,
            1,
            rectangles);

        gc_attributes[0] = screen->black_pixel;
        xcb_change_gc(
            connection,
            gc,
            /* valuemask = */ XCB_GC_FOREGROUND,
            /* values = */ gc_attributes);

        xcb_point_t points[2];

        points[0].x = X1 + (state & 255);
        points[0].y = Y1;
        points[1].x = X2 - (state & 255);
        points[1].y = Y2;

        xcb_poly_line(
            connection,
            XCB_COORD_MODE_ORIGIN,
            window,
            gc,
            2,
            points);

        xcb_flush(connection);

        needs_redraw = false;
    }
} // end while

